statement:
Given an integer `n`, build the array `nums` of length `n + 1` (indices `0` to `n`) using these rules:

- `nums[0] = 0` and `nums[1] = 1`;
- for every `i` with `2 <= 2 * i <= n`, `nums[2 * i] = nums[i]`;
- for every `i` with `2 <= 2 * i + 1 <= n`, `nums[2 * i + 1] = nums[i] + nums[i + 1]`.

Return the largest value in `nums`.

validator:
function validate([n]) {
  if (n < 0 || n > 100) return 'n is between 0 and 100.';
  return null;
}

reference:
function getMaximumGenerated(n) {
  if (n === 0) {
    return 0;
  }
  const nums = new Array(n + 1).fill(0);
  nums[1] = 1;
  let best = 1;
  for (let i = 2; i <= n; i++) {
    const half = Math.floor(i / 2);
    if (i % 2 === 0) {
      nums[i] = nums[half];
    } else {
      nums[i] = nums[half] + nums[half + 1];
    }
    best = Math.max(best, nums[i]);
  }
  return best;
}

